const { withGradleProperties } = require('expo/config-plugins');

// The template's 2 GB Gradle heap runs R8 out of memory on a local release
// build ("JVM garbage collector is thrashing", 1.1.5 on 2026-09-27). Set here
// because android/ is regenerated by every prebuild, which drops a hand edit.
const JVM_ARGS = '-Xmx4096m -XX:MaxMetaspaceSize=1024m';

module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (mod) => {
    const props = mod.modResults.filter((p) => !(p.type === 'property' && p.key === 'org.gradle.jvmargs'));
    props.push({ type: 'property', key: 'org.gradle.jvmargs', value: JVM_ARGS });
    mod.modResults = props;
    return mod;
  });
};
